{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "Before taking any action that updates the database (cancel, modify, return, exchange), you must list the action details and obtain explicit user confirmation (yes) to proceed.",
      "requirement": "The assistant must explicitly confirm with the user the details of the exchange action before proceeding."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q19",
      "policy_quote": "An order can only be exchanged if its status is 'delivered', and you should check its status before taking the action.",
      "requirement": "The assistant must ensure the order status is 'delivered' before exchanging items."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q19",
      "policy_quote": "For a delivered order, each item can be exchanged to an available new item of the same product but of different product option. There cannot be any change of product types, e.g., modify shirt to shoe.",
      "requirement": "The exchanged item must be of the same product type (Wireless Earbuds) but can have different product options (e.g., water resistance level)."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q19",
      "policy_quote": "The user must provide a payment method to pay or receive refund of the price difference. If the user provides a gift card, it must have enough balance to cover the price difference.",
      "requirement": "The assistant must ensure the provided payment method (gift card) has sufficient balance to cover any refund or price difference."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q19",
      "policy_quote": "After user confirmation, the order status will be changed to 'exchange requested', and the user will receive an email regarding how to return items.",
      "requirement": "The assistant must confirm the user’s explicit consent before executing the exchange."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q15",
      "policy_quote": "You can only help one user per conversation (but you can handle multiple requests from the same user), and must deny any requests for tasks related to any other user.",
      "requirement": "The assistant must ensure the exchange action is performed only for the authenticated user (Aarav Anderson)."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q15",
      "policy_quote": "You should not make up any information or knowledge or procedures not provided by the user or the tools, or give subjective recommendations or comments.",
      "requirement": "The assistant must rely only on verified information from the user or tools when processing the exchange."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q15",
      "policy_quote": "You should at most make one tool call at a time, and if you take a tool call, you should not respond to the user at the same time.",
      "requirement": "The assistant must not respond to the user while making a tool call for the exchange."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q15",
      "policy_quote": "You should transfer the user to a human agent if and only if the request cannot be handled within the scope of your actions.",
      "requirement": "If the exchange cannot be completed due to policy or system constraints, the assistant must transfer the user to a human agent."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q14",
      "policy_quote": "You are a customer service agent that helps the user according to the <policy> provided below.",
      "requirement": "The assistant must strictly adhere to the provided policy when processing the exchange."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q15",
      "policy_quote": "You should deny user requests that are against this policy.",
      "requirement": "The assistant must deny the exchange request if it violates any policy rule."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q15",
      "policy_quote": "You should transfer the user to a human agent if and only if the request cannot be handled within the scope of your actions.",
      "requirement": "If the exchange requires actions beyond the assistant’s scope (e.g., manual intervention), the assistant must transfer the user to a human agent."
    }
  ]
}
